  function restoreTabData({ uiPrefsOnly = false } = {}) {
    try {
      const saved = localStorage.getItem(getScopedTabDataStorageKey(stateManager2.getSessionId()));
      if (saved) {
        const data = JSON.parse(saved);
        const age = Date.now() - (data.timestamp || 0);
        if (age < 24 * 60 * 60 * 1e3) {
          if (!uiPrefsOnly) {
            if (data.tabData) {
              Object.entries(data.tabData).forEach(([tab, value]) => {
                stateManager2.setTabData(tab, value);
              });
            }
            if (data.pendingRecommendations) {
              window.pendingRecommendations = data.pendingRecommendations;
            }
            if (data.interactiveState) {
              stateManager2.setInteractiveState(data.interactiveState);
            }
          }
          if (data.activeReviewPane) {
            window._activeReviewPane = data.activeReviewPane;
          }
          log14.info(`Restored tab data from localStorage (uiPrefsOnly=${uiPrefsOnly})`);
        } else {
          localStorage.removeItem(getScopedTabDataStorageKey(stateManager2.getSessionId()));
        }
      }
    } catch (error) {
      log14.warn("Failed to restore tab data:", error);
    }
  }

