    const wcLabel = isAcademic ? `${wcTarget.lo}\u2013${wcTarget.hi} (academic/research)` : isExec ? `${wcTarget.lo}\u2013${wcTarget.hi} (executive)` : `\u2264${wcTarget.hi} (standard)`;
    const words = text2.trim().split(/\s+/).filter(Boolean).length;
    const wcPct = Math.min(100, words / wcTarget.hi * 100);
    const wcColour = words < wcTarget.warnLo ? "#ef4444" : words < wcTarget.lo ? "#f59e0b" : words <= wcTarget.hi ? "#22c55e" : words <= wcTarget.warnHi ? "#f59e0b" : "#ef4444";
    const wcStatus = words >= wcTarget.lo && words <= wcTarget.hi ? "pass" : words >= wcTarget.warnLo && words <= wcTarget.warnHi ? "warn" : "fail";
    const wcBar = `<span class="cl-wc-bar"><span class="cl-wc-fill" style="width:${wcPct}%;background:${wcColour};"></span></span>`;
    const wordCountCheck = {
      [wcStatus]: true,
      label: `Word count (${wcLabel})`,
      detail: `${words} words ${wcBar} \u2014 ${words < wcTarget.lo ? `too short; aim for ${wcTarget.lo}\u2013${wcTarget.hi}.` : words > wcTarget.hi ? `too long; trim to ${wcTarget.hi} words.` : "within target range."}`
    };
    const lastPara = text2.split(/\n{2,}/).filter((p) => p.trim()).slice(-1)[0] || "";
    const assertiveCtaPatterns = [
      /interview/i,
      /discuss/i,
      /opportunity to (speak|talk|meet|connect)/i,
      /i will (call|follow.?up|reach out|contact|send)/i,
      /i (plan|intend) to/i,
      /welcome the chance/i,
      /available (for|to)/i,
      /contact me/i
    ];
    const passiveCtaPatterns = [
      /hear from you/i,
      /look forward to (your|hearing)/i,
      /await(ing)? your/i,
      /hope to (hear|meet)/i
    ];
    const hasAssertiveCta = assertiveCtaPatterns.some((re2) => re2.test(lastPara));
    const hasPassiveCta = passiveCtaPatterns.some((re2) => re2.test(lastPara));
    const ctaCheck = {
      pass: hasAssertiveCta,
      fail: !hasAssertiveCta && hasPassiveCta,
      label: "Call-to-action closing",
      detail: hasAssertiveCta ? "Assertive call-to-action \u2014 takes initiative." : hasPassiveCta ? 'Passive closing rejected \u2014 phrases like "I look forward to hearing from you" are too passive. Replace with a direct interview request: "I would welcome the opportunity to interview" or "I will follow up next week."' : "No call-to-action found \u2014 add a direct interview request or proactive follow-up statement."
    };
    const achievementPatterns = [
      /\d+%/,
      // percentages
      /\$[\d,]+/,
      // dollar amounts
      /\d+ (times|x|fold|year|month|week|day|team|people|staff|client|customer|project|product|system|award|patent)/i,
      /reduced|increased|grew|grew|doubled|tripled|saved|generated|delivered|launched|led|built|designed|architected|pioneered|won|awarded|earned|achieved/i
    ];
